test('bulk discount is applied once, after the customer discount (#12)', () => {
  assert.equal(total(lines(10, 1000), 0.1), 8550);
});

test('bulk discount without customer discount', () => {
  assert.equal(total(lines(10, 1000)), 9500);
  assert.equal(total(lines(10, 1000), 0), 9500);
});

test('fractions of a yen are dropped', () => {
  assert.equal(total(lines(10, 11)), 104); // 110 * 0.95 = 104.5
  assert.equal(total([{ price: 995, qty: 1 }], 0.1), 895); // 895.5
